from __future__ import annotations

from typing import Any

from ...core.http import HttpClient
from ...core.models import Confidence, Finding, Status
from ...core.versions import parse_version_required, parse_version_safe

CVE_ID = "CVE-2026-111497"
NAME = "Node.js Brotli decoder out-of-bounds write (Node2Shell)"
RULE = "Node.js 22.x before 22.23.4, 24.x before 24.22.1, 26.x before 26.12.1; EOL lines remain affected"
TYPE = "Remote Code Execution"

# A tiny valid stream generated by Node's Brotli encoder.  It decompresses to a
# harmless marker and is deliberately unrelated to the public crash/RCE payload.
_VALID_BROTLI = bytes.fromhex("8b0c8050726f6f66434d5320736166652042726f746c692070726f626503")


def classify_version(version: str | None) -> str:
    value = parse_version_safe(version)
    if value is None:
        return Status.DETECTED_VERSION_UNKNOWN
    major = value.release[0]
    if major == 22:
        return Status.PATCHED if value >= parse_version_required("22.23.4") else Status.LIKELY_VULNERABLE
    if major == 24:
        return Status.PATCHED if value >= parse_version_required("24.22.1") else Status.LIKELY_VULNERABLE
    if major == 26:
        return Status.PATCHED if value >= parse_version_required("26.12.1") else Status.LIKELY_VULNERABLE
    if major <= 25:
        return Status.LIKELY_VULNERABLE
    return Status.NOT_AFFECTED


def safe_brotli_probe(target_url: str, timeout: int, proxy: str | None) -> dict[str, Any]:
    """Send valid and truncated tiny Brotli bodies; never sends the exploit stream."""
    client = HttpClient(base_url=target_url, timeout=timeout, proxy=proxy)
    headers = {
        "Content-Type": "application/octet-stream",
        "Content-Encoding": "br",
        "X-ProofCMS-Probe": "node2shell-safe",
    }
    valid = client.post("/", data=_VALID_BROTLI, headers=headers, timeout=timeout)
    truncated = client.post("/", data=_VALID_BROTLI[:-1], headers=headers, timeout=timeout)
    valid_status = int(valid.get("status") or 0)
    truncated_status = int(truncated.get("status") or 0)
    return {
        "path": "/",
        "valid_status": valid_status,
        "truncated_status": truncated_status,
        "valid_body_hash": valid.get("body_hash"),
        "truncated_body_hash": truncated.get("body_hash"),
        "valid_error": valid.get("error"),
        "truncated_error": truncated.get("error"),
        "differential": bool(valid_status > 0 and truncated_status > 0 and valid_status != truncated_status),
    }


def check(
    target_url: str,
    cms_version: str | None = None,
    run_exploit_check: bool = False,
    timeout: int = 12,
    proxy: str | None = None,
    node_runtime: dict[str, Any] | None = None,
    **kwargs: Any,
) -> Finding:
    del cms_version, kwargs
    runtime = node_runtime or {}
    if not runtime.get("detected"):
        return Finding(
            CVE_ID,
            NAME,
            Status.NOT_DETECTED,
            Confidence.LOW,
            "Node.js runtime / zlib Brotli",
            affected_rule=RULE,
            exploit_available=True,
            detail="Node.js was not fingerprinted from explicit public HTTP evidence.",
            action="Verify the server-side runtime and Brotli request handling internally.",
            vulnerability_type=TYPE,
        )

    version = runtime.get("version")
    version_status = classify_version(version)
    evidence: dict[str, Any] = {
        "source": runtime.get("source"),
        "server": runtime.get("server"),
        "framework": runtime.get("framework"),
        "session_cookie": bool(runtime.get("session_cookie")),
        "safe_probe": False,
    }
    if version_status == Status.PATCHED:
        return Finding(
            CVE_ID,
            NAME,
            Status.PATCHED,
            Confidence.HIGH,
            "Node.js runtime / zlib Brotli",
            version,
            RULE,
            exploit_available=True,
            detail=f"Node.js {version} is at or beyond the upstream fixed release for its supported line.",
            action="Keep Node.js updated and restart running processes after security updates.",
            evidence=evidence,
            vulnerability_type=TYPE,
        )
    if version_status == Status.NOT_AFFECTED:
        return Finding(
            CVE_ID,
            NAME,
            Status.NOT_AFFECTED,
            Confidence.HIGH,
            "Node.js runtime / zlib Brotli",
            version,
            RULE,
            exploit_available=True,
            detail=f"Detected Node.js {version}, outside the affected release lines.",
            action="Continue using a supported Node.js release.",
            evidence=evidence,
            vulnerability_type=TYPE,
        )

    if version_status == Status.DETECTED_VERSION_UNKNOWN:
        result_status = Status.DETECTED_VERSION_UNKNOWN
        detail = "Node.js was detected, but its exact version was not exposed by public HTTP responses."
        confidence = Confidence.LOW
    else:
        result_status = Status.NOT_CONFIRMED
        detail = (
            f"Detected Node.js {version}, which is in an affected release line, but public HTTP responses do not "
            "by themselves establish that the application accepts attacker-controlled Brotli request bodies."
        )
        confidence = Confidence.MEDIUM

    if run_exploit_check:
        probe = safe_brotli_probe(target_url, timeout, proxy)
        evidence.update(probe, safe_probe=True)
        if probe["differential"]:
            if version_status == Status.DETECTED_VERSION_UNKNOWN:
                result_status = Status.INCONCLUSIVE
                confidence = Confidence.MEDIUM
                detail = (
                    "A Node.js-like runtime was detected and valid versus truncated Brotli request bodies produced "
                    "different responses, indicating a decompression path; the runtime version is unknown, so the "
                    "CVE cannot be confirmed from public evidence."
                )
            else:
                result_status = Status.LIKELY_VULNERABLE
                confidence = Confidence.HIGH
                detail = (
                    f"Node.js {version} is in the affected range and the safe valid/truncated Brotli differential "
                    "indicates that this endpoint processes attacker-controlled Brotli request bodies. No crash or "
                    "RCE payload was sent."
                )
        else:
            detail += " The safe valid/truncated Brotli differential did not establish request-body decompression."

    return Finding(
        CVE_ID,
        NAME,
        result_status,
        confidence,
        "Node.js runtime / zlib Brotli",
        version,
        RULE,
        exploit_available=True,
        exploit_ran=run_exploit_check,
        detail=detail,
        action="Upgrade to Node.js 22.23.4, 24.22.1, or 26.12.1 (or a newer supported release), then restart the process. As a temporary defense, reject Brotli-encoded request bodies at the edge.",
        proof_url=target_url if run_exploit_check else None,
        evidence=evidence,
        vulnerability_type=TYPE,
    )


def metadata() -> dict[str, Any]:
    return {
        "cve": CVE_ID,
        "cms": "generic",
        "name": NAME,
        "component": "Node.js runtime / zlib Brotli",
        "affected_rule": RULE,
        "affected_versions": ["22.x <22.23.4", "24.x <24.22.1", "26.x <26.12.1", "EOL lines"],
        "exploit_available": True,
        "exploit_modes": ["safe"],
        "intrusive": False,
        "vulnerability_type": TYPE,
        "required_detectors": ["node"],
        "references": [
            "https://github.com/Rabbitbong/node2shell",
            "https://nvd.nist.gov/vuln/detail/CVE-2026-111497",
        ],
    }
